INSERT INTO public.priests ("id", "name", "title", "photo_url", "short_bio", "full_bio", "ordination_year", "parish_since", "is_active", "created_at", "updated_at", "cloudinary_public_id", "video_url", "video_thumbnail_url", "video_description") VALUES ('7a6e5b05-2cdd-4983-8190-5f01457dce2b', 'Dom Algacir Munhak', 'Bispo Diocesano', 'https://res.cloudinary.com/dtar7lkdz/image/upload/v1762684846/parish/boskwiphqmrz0qk0yliu.jpg', 'Dom Algacir Munhak nasceu em São João D´Oeste, distrito do município de Cascavel (PR), no dia 19 de abril de 1966. É o quinto filho de Albino Munhak (in memorian) e Joana Kroprochinski Munhak, tendo como irmãos Alésio, Otilindes, Marli, Geneci e Marislei. Em dezembro de 1979, fez o estágio vocacional em São Miguel do Iguaçu (PR), para, depois, ingressar no Seminário São Rafael, em Casca (RS), no dia 3 de março de 1980, na Congregação dos Missionários de São Carlos, Scalabrinianos.', '
INSERT INTO public.priests ("id", "name", "title", "photo_url", "short_bio", "full_bio", "ordination_year", "parish_since", "is_active", "created_at", "updated_at", "cloudinary_public_id", "video_url", "video_thumbnail_url", "video_description") VALUES ('14b59d80-4d8d-40bb-8b9b-291609e113c0', 'Padre Márcio Rodrigues', 'Pároco', 'https://res.cloudinary.com/dtar7lkdz/image/upload/v1755820699/parish/zjyvmkibczho1v0j2q1i.jpg', 'Sacerdote da Diocese de São Miguel Paulista - SP ', 'Ordenado em 20 de agosto de 2016, trilhou uma sólida trajetória formativa. Graduou-se em Filosofia pela UNIFAI e em Teologia pela PUC São Paulo, aprofundando posteriormente sua missão pastoral com pós-graduação em Formação pela Faculdade Dehoniana de Taubaté. Tomou posse em nossa paróquia em 6 de janeiro de 2019, onde continua a servir com dedicação, cuidado pastoral e compromisso com a evangelização.', 2016, 2019, true, '2025-08-18T12:27:59.707471+00:00', '2026-01-28T13:58:42.423+00:00', NULL, 'https://res.cloudinary.com/dtar7lkdz/video/upload/v1763039248/priests/qvnqctg3ko68crgxva4o.mp4', 'https://res.cloudinary.com/dtar7lkdz/video/upload/v1763039248/priests/qvnqctg3ko68crgxva4o.jpg', NULL) ON CONFLICT (id) DO NOTHING;
