INSERT INTO public.parish_announcements ("id", "type", "title", "content", "event_date", "is_published", "created_at", "updated_at", "whatsapp_contact", "flyer_url", "slug") VALUES ('bc69db4f-68c5-42fc-ab66-c9e3d583b17a', 'event', '2º Dia da Novena de São Miguel Arcanjo | 13 de Agosto', 'Vivencie conosco o 2º dia da Novena de São Miguel Arcanjo, com a presença do Pe. Roberto Eudes. 🙏✨
INSERT INTO public.parish_announcements ("id", "type", "title", "content", "event_date", "is_published", "created_at", "updated_at", "whatsapp_contact", "flyer_url", "slug") VALUES ('5f9ff6f1-a37d-4084-bc23-55766d660286', 'announcement', 'Casamento Comunitário 2026 – Inscrições Abertas', 'A Pastoral Familiar da Paróquia Senhor Santo Cristo dos Milagres convida os casais que desejam regularizar sua situação matrimonial e receber o Sacramento do Matrimônio para participarem do Casamento Comunitário 2026.
INSERT INTO public.parish_announcements ("id", "type", "title", "content", "event_date", "is_published", "created_at", "updated_at", "whatsapp_contact", "flyer_url", "slug") VALUES ('5b8e2f51-f24a-48ba-948d-1dc686ce9b28', 'announcement', 'Mensagem aos Dizimistas', 'A Paróquia agradece, com carinho, a fidelidade e a generosidade de todos os dizimistas, que reconhecem no dízimo um gesto de gratidão a Deus e um compromisso com a missão evangelizadora. Através dessa partilha, colaboramos para que a Igreja continue anunciando o Evangelho e servindo à comunidade.
INSERT INTO public.parish_announcements ("id", "type", "title", "content", "event_date", "is_published", "created_at", "updated_at", "whatsapp_contact", "flyer_url", "slug") VALUES ('d27e8dad-5957-48af-aea6-572e4262eb26', 'announcement', 'Minuto do Dízimo: A Água Viva que Transborda em Partilha', 'Inspirado no Evangelho de João 4,5-42, que narra o encontro de Jesus com a Samaritana, somos convidados a refletir sobre o verdadeiro sentido do dízimo e da oferta.
INSERT INTO public.parish_announcements ("id", "type", "title", "content", "event_date", "is_published", "created_at", "updated_at", "whatsapp_contact", "flyer_url", "slug") VALUES ('2fb4b794-cd16-407f-a2f1-2e6a980aacb4', 'event', 'Santa Missa em Ação de Graças pelos 10 anos de Ordenação Sacerdotal', 'A Paróquia Senhor Santo Cristo dos Milagres convida você e sua família para uma celebração especial em Ação de Graças pelos 10 anos de Ordenação Sacerdotal do Pe. Márcio. 🙏✨
INSERT INTO public.parish_announcements ("id", "type", "title", "content", "event_date", "is_published", "created_at", "updated_at", "whatsapp_contact", "flyer_url", "slug") VALUES ('9f948d0d-ef6f-48a3-a19c-6b5e8e9ff3b9', 'announcement', 'Dízimo', 'O dízimo é um gesto de fé e partilha que contribui para o sustento da Igreja e suas obras pastorais, missionárias e sociais.
INSERT INTO public.parish_announcements ("id", "type", "title", "content", "event_date", "is_published", "created_at", "updated_at", "whatsapp_contact", "flyer_url", "slug") VALUES ('17097db5-d8d2-48b9-8874-c58f21becdb1', 'event', '3º Encontro com Cristo (EJC) – Uma Nova Vida em Cristo', 'O Grupo de Jovens Vida Nova convida você para viver uma experiência transformadora no 3º Encontro com Cristo (EJC).
INSERT INTO public.parish_announcements ("id", "type", "title", "content", "event_date", "is_published", "created_at", "updated_at", "whatsapp_contact", "flyer_url", "slug") VALUES ('39db2379-1527-40c4-a057-b94dadb85327', 'event', 'Novena de São Miguel Arcanjo 2026', 'A Paróquia Senhor Santo Cristo dos Milagres convida toda a comunidade para a tradicional Novena de São Miguel Arcanjo, de 06 de agosto a 01 de outubro, sempre às 20h.
INSERT INTO public.blog_posts ("id", "title", "content", "excerpt", "featured_image", "author", "is_published", "created_at", "updated_at", "slug", "cloudinary_public_id") VALUES ('6ecc42fb-e00a-4a37-9db3-22ed2bd25794', 'Sobre a Paróquia', '<p class="ql-align-justify"><span style="color: rgb(55, 65, 81);">Paróquia Senhor Santo Cristo dos Milagres – 40 anos de fé e missão Há quatro décadas, em meio à fé simples e perseverante do povo de Cidade Tiradentes, nasceu a Paróquia Senhor Santo Cristo dos Milagres. Sua história se confunde com a própria caminhada da comunidade, marcada por desafios, conquistas e, sobretudo, pela confiança no Cristo que conduz e fortalece seu povo. </span></p><p class="ql-align-justify"><span style="color: rgb(55, 65, 81);">No início dos anos 1980, a região ainda dava seus primeiros passos como bairro em crescimento, recebendo inúmeras famílias vindas de diversas partes de São Paulo e do interior. Foi nesse contexto que missionários, padres e leigos se uniram para organizar a vida de fé, celebrando as primeiras missas em espaços improvisados, sempre movidos pelo desejo de cultivar a esperança e o amor de Deus no coração da comunidade. </span></p><p class="ql-align-justify"><span style="color: rgb(55, 65, 81);">Com o tempo, a devoção ao Senhor Santo Cristo dos Milagres se tornou o sinal da identidade paroquial. Inspirados por Ele, que acolhe as dores e milagres do povo, a paróquia cresceu em estrutura e, mais ainda, em fraternidade. Salas pastorais foram construídas, capelas erguidas, movimentos e pastorais se fortaleceram. A juventude encontrou espaço de protagonismo, as famílias puderam viver sua fé em comunidade, e a solidariedade se tornou marca registrada da paróquia. </span></p><p class="ql-align-justify"><span style="color: rgb(55, 65, 81);">Ao longo desses 40 anos, incontáveis crianças foram batizadas, jovens receberam a crisma, casais celebraram o sacramento do matrimônio e muitos fiéis se despediram desta vida na certeza da ressurreição. Cada celebração, cada encontro, cada gesto de serviço compõe a memória viva desta paróquia que é casa de oração, de comunhão e de missão. </span></p><p class="ql-align-justify"><span style="color: rgb(55, 65, 81);">﻿Hoje, celebrando seus 40 anos, a Paróquia Senhor Santo Cristo dos Milagres olha para trás com gratidão e para frente com esperança. Gratidão pela caminhada feita por tantos padres, religiosas, lideranças e fiéis leigos que não mediram esforços para construir uma comunidade viva. E esperança, porque a obra de Deus continua, chamando cada geração a ser sal da terra e luz do mundo em Cidade Tiradentes. Que este jubileu seja tempo de renovar a fé, fortalecer os laços comunitários e continuar a missão de anunciar o Evangelho, sob a proteção do Senhor Santo Cristo dos Milagres, que jamais abandona seu povo. Paróquia Senhor Santo Cristo dos Milagres – 40 anos de bênçãos, milagres e fé!</span></p>', 'Paróquia Senhor Santo Cristo dos Milagres – 40 anos de fé e missão Há quatro décadas, em meio à fé simples e perseverante do povo de Cidade Tiradentes, nasceu a Paróquia Senhor Santo Cristo dos Milagres.', 'https://res.cloudinary.com/dtar7lkdz/image/upload/v1755803131/parish/cesqtgtowoibh5zjcqlx.jpg', 'Pascom', true, '2025-08-16T20:47:49.26139+00:00', '2025-11-07T18:16:04.988+00:00', 'sobre-a-parquia', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.video_testimonials ("id", "name", "description", "video_type", "video_url", "cloudinary_public_id", "youtube_id", "thumbnail_url", "order_index", "is_active", "created_at", "updated_at") VALUES ('0523564b-8f4a-46b5-8240-3b92775e4d58', 'Onde a Fé Nasce e Floresce', 'No dia do Batismo, Deus lançou a semente da fé no coração.
INSERT INTO public.video_testimonials ("id", "name", "description", "video_type", "video_url", "cloudinary_public_id", "youtube_id", "thumbnail_url", "order_index", "is_active", "created_at", "updated_at") VALUES ('3d814918-dfdb-4d98-9d5b-c51d8d2d99ea', 'Ordenação Diaconal de Adamo – Um Chamado ao Serviço de Cristo', 'Um dia que ficará para sempre marcado na história de nossa paróquia. Com grande alegria e gratidão a Deus, celebramos a Ordenação Diaconal de Adamo, um momento de fé, emoção e entrega ao serviço da Igreja.
INSERT INTO public.video_testimonials ("id", "name", "description", "video_type", "video_url", "cloudinary_public_id", "youtube_id", "thumbnail_url", "order_index", "is_active", "created_at", "updated_at") VALUES ('f4652993-8c34-499b-9a3a-081fb445a111', '4º Retiro de Mulheres', 'Um chamado especial para você, mulher, que deseja viver um dia de encontro profundo com Deus 💙
INSERT INTO public.video_testimonials ("id", "name", "description", "video_type", "video_url", "cloudinary_public_id", "youtube_id", "thumbnail_url", "order_index", "is_active", "created_at", "updated_at") VALUES ('73273c43-1eda-4d11-abc6-18c396ecf8dc', 'Retiro para Mulheres', 'No dia 17/05/26 , você é nossa convidada para viver um Retiro de Mulheres, um tempo preparado com carinho para oração, silêncio e encontro profundo com Deus. Será um dia de acolhimento, renovação da fé e cuidado do coração, onde cada mulher poderá se fortalecer e se deixar conduzir pelo amor do Senhor. Venha como você está e permita-se viver esse chamado especial. ', 'upload', 'https://res.cloudinary.com/dtar7lkdz/video/upload/v1769270369/videos/d3do8ghhs8avccnv9n7w.mp4', NULL, NULL, 'https://res.cloudinary.com/dtar7lkdz/video/upload/v1769270369/videos/d3do8ghhs8avccnv9n7w.jpg', 1, true, '2026-01-24T16:02:07.028268+00:00', '2026-01-28T14:15:18.183202+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.photo_albums ("id", "name", "description", "cover_image_url", "cloudinary_public_id", "is_active", "order_index", "created_at", "updated_at", "slug") VALUES ('445b6354-dfee-41d7-a63f-0b4bc0bd37de', 'Domingo dos Pais e do Dízimo | Um Dia de Gratidão e Fé', 'Neste domingo especial, queremos celebrar com alegria o Dia dos Pais e também viver o Domingo do Dízimo, agradecendo a Deus por todas as bênçãos recebidas. 🙏💙
INSERT INTO public.photo_albums ("id", "name", "description", "cover_image_url", "cloudinary_public_id", "is_active", "order_index", "created_at", "updated_at", "slug") VALUES ('381788de-9132-45b9-837f-2dad7ea62528', 'Caminhando e Aprendendo Juntos', 'Entre reuniões, partilhas e formações, vamos construindo muito mais do que projetos — construímos comunhão.
INSERT INTO public.photo_albums ("id", "name", "description", "cover_image_url", "cloudinary_public_id", "is_active", "order_index", "created_at", "updated_at", "slug") VALUES ('5524075f-0a04-49fa-a314-47e874bb6328', '5º Cerco de Jericó – Muralhas caíram, milagres aconteceram', 'O 5º Cerco de Jericó ficará marcado em nossos corações como um tempo de entrega, perseverança e encontro com Deus. Foram dias em que nossa comunidade se uniu em oração, pedindo que o Senhor derrubasse as muralhas que impedem a ação da Sua graça em nossas vidas.
INSERT INTO public.photos ("id", "title", "description", "image_url", "category", "created_at", "cloudinary_public_id", "album_id") VALUES ('2e4583f3-275c-420f-9b6b-9a33ab854413', '1º Domingo do Advento', '', 'https://res.cloudinary.com/dtar7lkdz/image/upload/v1764944379/photos/nznvounxblffdi0w6vkc.webp', 'community', '2025-12-05T14:19:39.896666+00:00', 'photos/nznvounxblffdi0w6vkc', NULL) ON CONFLICT (id) DO NOTHING;
