INSERT INTO public.urgent_popups ("id", "title", "content", "image_url", "cloudinary_public_id", "link_url", "link_text", "is_active", "priority", "auto_close_seconds", "created_at", "updated_at") VALUES ('145e0e00-fe62-4d56-ae2a-b09555943938', 'Inscrições Abertas – EJC Vida Nova em Cristo', 'O Encontro de Jovens com Cristo é um convite para viver uma experiência única de fé, encontro e renovação. Um tempo especial para jovens que desejam se aproximar de Deus, refletir sobre a vida e descobrir uma verdadeira Vida Nova em Cristo.
