-- Função: set_blog_post_slug
CREATE OR REPLACE FUNCTION public.set_blog_post_slug()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
  base_slug TEXT;
  final_slug TEXT;
  counter INTEGER := 0;
BEGIN
  -- Only generate slug if it's empty or null
  IF NEW.slug IS NULL OR NEW.slug = '' THEN
    base_slug := generate_slug(NEW.title);
    final_slug := base_slug;
    
    -- Check for uniqueness and add counter if needed
    WHILE EXISTS (
      SELECT 1 FROM blog_posts 
      WHERE slug = final_slug 
      AND id != COALESCE(NEW.id, '')
    ) LOOP
      counter := counter + 1;
      final_slug := base_slug || '-' || counter;
    END LOOP;
    
    NEW.slug := final_slug;
  END IF;
  
  RETURN NEW;
END;
$function$;

-- Função: set_campaign_slug
CREATE OR REPLACE FUNCTION public.set_campaign_slug()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
  base_slug TEXT;
  final_slug TEXT;
  counter INTEGER := 0;
BEGIN
  IF NEW.slug IS NULL OR NEW.slug = '' THEN
    base_slug := generate_slug(NEW.title);
    final_slug := base_slug;

    WHILE EXISTS (
      SELECT 1 FROM campaigns
      WHERE slug = final_slug
        AND id != COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
    ) LOOP
      counter := counter + 1;
      final_slug := base_slug || '-' || counter;
    END LOOP;

    NEW.slug := final_slug;
  END IF;

  RETURN NEW;
END;
$function$;

-- Função: set_photo_album_slug
CREATE OR REPLACE FUNCTION public.set_photo_album_slug()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
  base_slug TEXT;
  final_slug TEXT;
  counter INTEGER := 0;
BEGIN
  IF NEW.slug IS NULL OR NEW.slug = '' THEN
    base_slug := generate_slug(NEW.name);
    final_slug := base_slug;

    WHILE EXISTS (
      SELECT 1 FROM photo_albums
      WHERE slug = final_slug
        AND id != COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
    ) LOOP
      counter := counter + 1;
      final_slug := base_slug || '-' || counter;
    END LOOP;

    NEW.slug := final_slug;
  END IF;

  RETURN NEW;
END;
$function$;

-- Função: set_parish_announcement_slug
CREATE OR REPLACE FUNCTION public.set_parish_announcement_slug()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
  base_slug TEXT;
  final_slug TEXT;
  counter INTEGER := 0;
  exists_conflict BOOLEAN;
BEGIN
  -- If slug is NULL/empty, generate from title
  IF NEW.slug IS NULL OR NEW.slug = '' THEN
    base_slug := generate_slug(NEW.title);
    final_slug := base_slug;

    LOOP
      IF TG_OP = 'UPDATE' AND NEW.id IS NOT NULL THEN
        SELECT EXISTS(
          SELECT 1 FROM parish_announcements
          WHERE slug = final_slug AND id <> NEW.id
        ) INTO exists_conflict;
      ELSE
        SELECT EXISTS(
          SELECT 1 FROM parish_announcements
          WHERE slug = final_slug
        ) INTO exists_conflict;
      END IF;

      EXIT WHEN NOT exists_conflict;

      counter := counter + 1;
      final_slug := base_slug || '-' || counter;
    END LOOP;

    NEW.slug := final_slug;

  -- If user supplied a slug, clean it
  ELSE
    NEW.slug := generate_slug(NEW.slug);
  END IF;

  RETURN NEW;
END;
$function$;

